CREATE TABLE IF NOT EXISTS drive_document_list_revisions ( organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, scope TEXT NOT NULL, revision TEXT NOT NULL, PRIMARY KEY (organization_id, scope) );
CREATE TABLE IF NOT EXISTS drive_contributor_revision ( id INTEGER PRIMARY KEY CHECK (id=1), revision TEXT NOT NULL );
CREATE INDEX IF NOT EXISTS document_shortcuts_by_folder ON document_shortcuts(folder_id);

CREATE TRIGGER IF NOT EXISTS drive_list_documents_insert AFTER INSERT ON documents BEGIN INSERT INTO drive_document_list_revisions(organization_id,scope,revision) SELECT organization_id,coalesce(scope,home_folder_id),lower(hex(randomblob(16))) FROM (SELECT * FROM (SELECT NEW.organization_id AS organization_id,NEW.home_folder_id AS home_folder_id) WHERE organization_id IN (SELECT id FROM organizations)) CROSS JOIN (SELECT 'all' AS scope UNION ALL SELECT NULL) WHERE scope IS NOT NULL OR home_folder_id IS NOT NULL ON CONFLICT(organization_id,scope) DO UPDATE SET revision=excluded.revision; END;
CREATE TRIGGER IF NOT EXISTS drive_list_versions_insert AFTER INSERT ON versions BEGIN INSERT INTO drive_document_list_revisions(organization_id,scope,revision) SELECT organization_id,coalesce(scope,home_folder_id),lower(hex(randomblob(16))) FROM (SELECT organization_id,home_folder_id FROM documents WHERE id IN (SELECT NEW.document_id)) CROSS JOIN (SELECT 'all' AS scope UNION ALL SELECT NULL) WHERE scope IS NOT NULL OR home_folder_id IS NOT NULL ON CONFLICT(organization_id,scope) DO UPDATE SET revision=excluded.revision; END;
CREATE TRIGGER IF NOT EXISTS drive_list_document_activity_insert AFTER INSERT ON document_activity BEGIN INSERT INTO drive_document_list_revisions(organization_id,scope,revision) SELECT organization_id,coalesce(scope,home_folder_id),lower(hex(randomblob(16))) FROM (SELECT organization_id,home_folder_id FROM documents WHERE id IN (SELECT NEW.document_id WHERE NEW.event IN ('uploaded','replaced','edited','moved','version-restored','google-source-imported','google-pdf-converted'))) CROSS JOIN (SELECT 'all' AS scope UNION ALL SELECT NULL) WHERE scope IS NOT NULL OR home_folder_id IS NOT NULL ON CONFLICT(organization_id,scope) DO UPDATE SET revision=excluded.revision; END;
