CREATE TRIGGER IF NOT EXISTS drive_list_contributors_update AFTER UPDATE OF name,email ON users WHEN OLD.name IS NOT NEW.name OR OLD.email IS NOT NEW.email BEGIN INSERT INTO drive_contributor_revision(id,revision) VALUES(1,lower(hex(randomblob(16)))) ON CONFLICT(id) DO UPDATE SET revision=excluded.revision; END;
CREATE TRIGGER IF NOT EXISTS drive_list_folder_revision_cleanup AFTER DELETE ON folders BEGIN DELETE FROM drive_document_list_revisions WHERE organization_id=OLD.organization_id AND scope=OLD.id; END;
